<?php require __DIR__.'/../includes/functions.php'; admin_required(); $a=$pdo->query('SELECT * FROM about WHERE id=1')->fetch(); $msg=''; if($_SERVER['REQUEST_METHOD']==='POST'){try{$image=upload_image('image',$a['image']);$pdo->prepare('UPDATE about SET title=?,body=?,button_text=?,button_url=?,image=? WHERE id=1')->execute([$_POST['title'],$_POST['body'],$_POST['button_text'],$_POST['button_url'],$image]);$a=$pdo->query('SELECT * FROM about WHERE id=1')->fetch();$msg='Saved.';}catch(Throwable $e){$msg=$e->getMessage();}} ?><!doctype html><html><head><meta charset="utf-8"><title>About</title><link rel="stylesheet" href="admin.css"></head><body><div class="top"><div class="wrap"><b>About us</b><a href="index.php" style="color:#fff">← Admin</a></div></div><div class="wrap" style="padding:30px 0"><div class="card"><h2>Edit About / Hero</h2><p class="muted">Bu böyük blok screenshot-dakı əsas sahədir.</p><?php if($msg):?><p><?=e($msg)?></p><?php endif;?><form method="post" enctype="multipart/form-data"><label>Title</label><input name="title" value="<?=e($a['title'])?>" required><label>Text</label><textarea name="body" rows="7"><?=e($a['body'])?></textarea><label>Button text</label><input name="button_text" value="<?=e($a['button_text'])?>"><label>Button URL</label><input name="button_url" value="<?=e($a['button_url'])?>"><label>Hero image</label><input type="file" name="image" accept="image/jpeg,image/png,image/webp"><?php if($a['image']):?><p><img class="thumb" src="../<?=e($a['image'])?>"></p><?php endif;?><button class="button">Save changes</button></form></div></div></body></html>
